# Visual Game of Life (Toroidal)
**Category:** Visual State Machines  
**Difficulty:** Intermediate  
**Tags:** automata, state-machine, toroidal, neighbors

Conway’s Game of Life on the screen grid; edges wrap around (toroidal). Uses red channel > 0.5 as 'alive'.

```wgsl
// METADATA: Category=Visual State Machines, Difficulty=Intermediate, Tags=[automata,state-machine,toroidal]
@group(0) @binding(0) var cur_state: texture_2d<f32>;
@group(0) @binding(1) var nxt_state: texture_storage_2d<rgba8unorm, write>;

fn torus(p: vec2<i32>, dims: vec2<i32>) -> vec2<i32> {
  return vec2<i32>((p.x % dims.x + dims.x) % dims.x,
                   (p.y % dims.y + dims.y) % dims.y);
}
@compute @workgroup_size(8,8)
fn life_step(@builtin(global_invocation_id) gid: vec3<u32>) {
  let dims_u = textureDimensions(cur_state);
  let dims = vec2<i32>(dims_u);
  let c = vec2<i32>(gid.xy);
  if (any(c >= dims)) { return; }

  var alive_n = 0u;
  for (var dy: i32=-1; dy<=1; dy++) {
    for (var dx: i32=-1; dx<=1; dx++) {
      if (dx==0 && dy==0) { continue; }
      let s = textureLoad(cur_state, torus(c+vec2<i32>(dx,dy), dims), 0).r;
      if (s > 0.5) { alive_n++; }
    }
  }
  let me = textureLoad(cur_state, c, 0).r > 0.5;
  let survive = me && (alive_n==2u || alive_n==3u);
  let born    = (!me) && (alive_n==3u);
  let out = select(0.0, 1.0, survive || born);
  textureStore(nxt_state, gid.xy, vec4<f32>(out,0.0,0.0,1.0));
}
```

