# N×N Convolution (Kernel from Control Strip)
**Category:** Image/Signal Processing  
**Difficulty:** Intermediate  
**Tags:** convolution, kernel, filter, control-strip

Reads an N×N kernel from a control strip on row 0 and applies it over the image.

```wgsl
// METADATA: Category=Image/Signal Processing, Difficulty=Intermediate, Tags=[convolution,kernel,control-strip]
@group(0) @binding(0) var src_tex: texture_2d<f32>;
@group(0) @binding(1) var dst_tex: texture_storage_2d<rgba8unorm, write>;
@group(0) @binding(2) var<uniform> K: u32;           // kernel size (odd, e.g. 3,5,7)
@group(0) @binding(3) var<uniform> stride: u32;      // spacing of kernel values on row 0

fn kernel_at(ix: u32) -> f32 {
  let c = textureLoad(src_tex, vec2<i32>(i32(ix*stride), 0), 0).r;
  return c*2.0 - 1.0; // assume encoded in [0,1], map to [-1,1]
}

@compute @workgroup_size(16,16)
fn convolve(@builtin(global_invocation_id) gid: vec3<u32>) {
  let dims = textureDimensions(src_tex);
  if (any(gid.xy >= dims)) { return; }

  let half = i32(K)/2;
  var acc = 0.0;
  var k = 0u;
  for (var j: i32=-half; j<=half; j++) {
    for (var i: i32=-half; i<=half; i++) {
      let p = clamp(vec2<i32>(i32(gid.x)+i, i32(gid.y)+j), vec2<i32>(0), vec2<i32>(dims)-1);
      let w = kernel_at(k); k++;
      acc += textureLoad(src_tex, p, 0).r * w;
    }
  }
  acc = clamp(acc, 0.0, 1.0);
  textureStore(dst_tex, gid.xy, vec4<f32>(acc,acc,acc,1.0));
}
```

