# Sobel Edge Detector
**Category:** Image/Signal Processing  
**Difficulty:** Beginner  
**Tags:** sobel, gradient, edge-detect

Classic Sobel operator using luminance, emits edge magnitude.

```wgsl
// METADATA: Category=Image/Signal Processing, Difficulty=Beginner, Tags=[sobel,edge]
@group(0) @binding(0) var src_tex: texture_2d<f32>;
@group(0) @binding(1) var dst_tex: texture_storage_2d<rgba8unorm, write>;

fn Y(rgb: vec3<f32>) -> f32 { return dot(rgb, vec3<f32>(0.299,0.587,0.114)); }

@compute @workgroup_size(16,16)
fn sobel(@builtin(global_invocation_id) gid: vec3<u32>) {
  let dims = textureDimensions(src_tex);
  if (any(gid.xy >= dims)) { return; }
  let x = i32(gid.x); let y = i32(gid.y);
  let w = i32(dims.x); let h = i32(dims.y);
  fn L(ix:i32,iy:i32)->f32{
    let p = vec2<i32>(clamp(ix,0,w-1), clamp(iy,0,h-1));
    return Y(textureLoad(src_tex,p,0).rgb);
  }
  let gx = -L(x-1,y-1)-2.0*L(x-1,y)-L(x-1,y+1)+L(x+1,y-1)+2.0*L(x+1,y)+L(x+1,y+1);
  let gy = -L(x-1,y-1)-2.0*L(x,y-1)-L(x+1,y-1)+L(x-1,y+1)+2.0*L(x,y+1)+L(x+1,y+1);
  let e = clamp(length(vec2<f32>(gx,gy)), 0.0, 1.0);
  textureStore(dst_tex, gid.xy, vec4<f32>(e,e,e,1.0));
}
```

