  let dims = textureDimensions(curr_tex);
  if (any(gid.xy >= dims)) { return; }
  let c = textureLoad(curr_tex, vec2<i32>(gid.xy), 0).rgb;
  let p = textureLoad(prev_tex, vec2<i32>(gid.xy), 0).rgb;
  let m = mix(p, c, clamp(alpha,0.0,1.0));
  textureStore(out_tex, gid.xy, vec4<f32>(m,1.0));
}
