# Screen-Driven Hash Noise
**Category:** Noise/Random  
**Difficulty:** Beginner  
**Tags:** noise, hash, stochastic

Deterministic hash-based noise per pixel, animated over frame index.

```wgsl
// METADATA: Category=Noise/Random, Difficulty=Beginner, Tags=[noise,hash]
@group(0) @binding(0) var out_tex : texture_storage_2d<rgba8unorm, write>;
@group(0) @binding(1) var<uniform> frame: u32;

fn hash31(p: vec3<u32>) -> f32 {
  var x = p.x*374761393u + p.y*668265263u + p.z*2246822519u;
  x = (x ^ (x>>13)) * 1274126177u;
  return f32(x) / 4294967295.0;
}

@compute @workgroup_size(16,16)
fn noise(@builtin(global_invocation_id) gid: vec3<u32>) {
  let dims = textureDimensions(out_tex);
  if (any(gid.xy >= dims)) { return; }
  let n = hash31(vec3<u32>(gid.x, gid.y, frame));
  textureStore(out_tex, gid.xy, vec4<f32>(n,n,n,1.0));
}
```

