# Row-wise Sum (Workgroup Reduction)
**Category:** Parallel Patterns  
**Difficulty:** Intermediate  
**Tags:** reduction, prefix, workgroup, shared-memory

Sums each 16-wide tile per row into one value using workgroup-shared memory; building block for scans.

```wgsl
// METADATA: Category=Parallel Patterns, Difficulty=Intermediate, Tags=[reduction,workgroup]
@group(0) @binding(0) var in_bus  : texture_storage_2d<r32float, read>;
@group(0) @binding(1) var out_bus : texture_storage_2d<r32float, write>;
var<workgroup> scratch: array<f32, 16>;

@compute @workgroup_size(16,1)
fn row_reduce(@builtin(global_invocation_id) gid: vec3<u32>,
              @builtin(local_invocation_index) lidx: u32,
              @builtin(workgroup_id) wgid: vec3<u32>) {
  let dims = textureDimensions(in_bus);
  if (gid.y >= dims.y) { return; }

  let base_x = wgid.x * 16u;
  let x = base_x + lidx;
  var v = 0.0;
  if (x < dims.x) {
    v = textureLoad(in_bus, vec2<i32>(i32(x), i32(gid.y))).r;
  }
  scratch[lidx] = v;
  workgroupBarrier();

  var stride = 8u;
  while (stride > 0u) {
    if (lidx < stride) { scratch[lidx] += scratch[lidx + stride]; }
    workgroupBarrier();
    stride >>= 1u;
  }
  if (lidx == 0u) {
    textureStore(out_bus, vec2<u32>(base_x, gid.y), vec4<f32>(scratch[0u],0.0,0.0,1.0));
  }
}
```

