# Screen-as-Queue (Ring Buffer Protocol)
**Category:** Data Structures  
**Difficulty:** Intermediate  
**Tags:** queue, ring-buffer, protocol, screen-bus

Implements a tiny ring buffer where head/tail are encoded in two pixels; pushes from an inbox pixel to queue row.

```wgsl
// METADATA: Category=Data Structures, Difficulty=Intermediate, Tags=[queue,ring-buffer,protocol]
// Depends on encode_float_to_rgba / decode_rgba_to_float (see encode-f32-rgba).
fn pack_u16x2(h: u32, t: u32) -> vec4<f32> {
  let combined = (h & 0xFFFFu) << 16u | (t & 0xFFFFu);
  // encode as bytes in RGBA
  return vec4<f32>(
    f32((combined >> 24u) & 0xFFu) / 255.0,
    f32((combined >> 16u) & 0xFFu) / 255.0,
    f32((combined >>  8u) & 0xFFu) / 255.0,
    f32( combined         & 0xFFu) / 255.0
  );
}
fn unpack_u16x2(c: vec4<f32>) -> vec2<u32> {
  let bits = (u32(c.r * 255.0) << 24u) |
             (u32(c.g * 255.0) << 16u) |
             (u32(c.b * 255.0) <<  8u) |
              u32(c.a * 255.0);
  return vec2<u32>((bits>>16u)&0xFFFFu, bits & 0xFFFFu);
}

@group(0) @binding(0) var screen_tex: texture_2d<f32>;
@group(0) @binding(1) var out_tex   : texture_storage_2d<rgba8unorm, write>;

@compute @workgroup_size(1,1)
fn queue_push(@builtin(global_invocation_id) gid: vec3<u32>) {
  let dims = textureDimensions(screen_tex);
  let Q = min(1024u, dims.x);                 // queue capacity fits width
  let ht = unpack_u16x2(textureLoad(screen_tex, vec2<i32>(0,4), 0)); // header at (0,4)
  let head = ht.x; let tail = ht.y;
  let next = (head + 1u) % Q;
  if (next == tail) { return; }               // full

  let datum = textureLoad(screen_tex, vec2<i32>(1,4), 0);           // inbox at (1,4)
  textureStore(out_tex, vec2<u32>(head, 5u), datum);                // ring row y=5
  textureStore(out_tex, vec2<u32>(0u, 4u), pack_u16x2(next, tail)); // advance head
}
```

